package com.bank.customer360.model;

import jakarta.persistence.*;
import java.util.*;

@Entity
@Table(name = "customers")
public class Customer {

    @Id
    @Column(name = "customer_id")
    private String customerId;

    private String name;
    private String email;

    // LAZY (default for @OneToMany): loaded ONLY when accessed → N+1 risk!
    @OneToMany(mappedBy = "customer", fetch = FetchType.LAZY)
    private List<Account> accounts = new ArrayList<>();

    // LAZY: another collection → cannot JOIN FETCH both Lists (MultipleBagFetchException!)
    @OneToMany(mappedBy = "customer", fetch = FetchType.LAZY)
    private Set<Nominee> nominees = new HashSet<>();  // Set avoids MultipleBagFetchException

    protected Customer() {}

    public String getCustomerId() { return customerId; }
    public String getName() { return name; }
    public String getEmail() { return email; }
    public List<Account> getAccounts() { return accounts; }
    public Set<Nominee> getNominees() { return nominees; }
}
