package com.bank.customer360.dto;

import com.bank.customer360.model.Customer;
import java.math.BigDecimal;
import java.util.List;

public record CustomerView(
    String customerId, String name, String email,
    List<AccountDetail> accounts, List<NomineeDetail> nominees
) {
    public record AccountDetail(String accountId, String type, BigDecimal balance) {}
    public record NomineeDetail(String name, String relationship) {}

    public static CustomerView from(Customer c) {
        return new CustomerView(c.getCustomerId(), c.getName(), c.getEmail(),
            c.getAccounts().stream().map(a -> new AccountDetail(a.getAccountId(), a.getType(), a.getBalance())).toList(),
            c.getNominees().stream().map(n -> new NomineeDetail(n.getNomineeName(), n.getRelationship())).toList());
    }
}
