package com.bank.customer360.repository;

import com.bank.customer360.model.Customer;
import org.springframework.data.jpa.repository.*;
import java.util.List;
import java.util.Optional;

public interface CustomerRepository extends JpaRepository<Customer, String> {

    // ═══ N+1 PROBLEM: findAll() loads customers, then LAZY accounts → N extra queries ═══
    // List<Customer> findAll(); // DO NOT use for loading with collections!

    // ═══ FIX 1: JOIN FETCH — one query for customer + accounts ═══
    @Query("SELECT c FROM Customer c JOIN FETCH c.accounts WHERE c.customerId = :id")
    Optional<Customer> findByIdWithAccounts(String id);

    // ═══ FIX 2: @EntityGraph — declarative fetch plan ═══
    @EntityGraph(attributePaths = {"accounts", "nominees"})
    @Query("SELECT c FROM Customer c WHERE c.customerId = :id")
    Optional<Customer> findByIdWithAll(String id);
    // EntityGraph fetches both collections — works because nominees is Set (not List)

    // ═══ FIX 3: @BatchSize via hibernate.default_batch_fetch_size=10 in config ═══
    // When accessing lazy collection on multiple customers:
    // Instead of N queries: SELECT * FROM accounts WHERE customer_id = ?  (per customer)
    // Batch: SELECT * FROM accounts WHERE customer_id IN (?,?,?,?,?,?,?,?,?,?)
    // 100 customers → 10 batch queries instead of 100 individual queries

    // ═══ DANGER: JOIN FETCH two Lists → MultipleBagFetchException ═══
    // This would FAIL if both accounts and nominees were List:
    // @Query("SELECT c FROM Customer c JOIN FETCH c.accounts JOIN FETCH c.nominees")
    // MultipleBagFetchException! Hibernate can't handle two List bags in one query.
    // FIX: use Set for one collection, OR fetch in separate queries

    // ═══ Separate queries approach (safest for multiple collections) ═══
    @Query("SELECT c FROM Customer c JOIN FETCH c.accounts")
    List<Customer> findAllWithAccounts();

    @Query("SELECT c FROM Customer c JOIN FETCH c.nominees")
    List<Customer> findAllWithNominees();
}
