package com.bank.customer360.service;

import com.bank.customer360.dto.CustomerView;
import com.bank.customer360.model.Customer;
import com.bank.customer360.repository.CustomerRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class CustomerService {

    private final CustomerRepository customerRepo;

    // JOIN FETCH: 1 query for customer + accounts
    @Transactional(readOnly = true)
    public CustomerView getWithAccounts(String customerId) {
        log.info("[JOIN FETCH] Loading customer {} with accounts — 1 query");
        Customer customer = customerRepo.findByIdWithAccounts(customerId)
            .orElseThrow(() -> new IllegalArgumentException("Not found: " + customerId));
        return CustomerView.from(customer);
    }

    // @EntityGraph: 1 query for customer + accounts + nominees
    @Transactional(readOnly = true)
    public CustomerView getFullView(String customerId) {
        log.info("[@EntityGraph] Loading customer {} with ALL collections — 1 query");
        Customer customer = customerRepo.findByIdWithAll(customerId)
            .orElseThrow(() -> new IllegalArgumentException("Not found: " + customerId));
        return CustomerView.from(customer);
    }

    // @BatchSize: loads lazy collections in batches when multiple customers accessed
    @Transactional(readOnly = true)
    public List<CustomerView> getAllWithBatchFetch() {
        log.info("[@BatchSize] Loading all customers — lazy collections batched by 10");
        List<Customer> customers = customerRepo.findAll();
        // Accessing accounts triggers batch: WHERE customer_id IN (10 IDs at a time)
        return customers.stream().map(CustomerView::from).toList();
    }
}
