package com.bank.customer360.controller;

import com.bank.customer360.dto.CustomerView;
import com.bank.customer360.service.CustomerService;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;
import java.util.List;

@RestController
@RequestMapping("/api/v1/customers")
@RequiredArgsConstructor
public class CustomerController {

    private final CustomerService customerService;

    @GetMapping("/{id}/with-accounts")
    public CustomerView withAccounts(@PathVariable String id) {
        return customerService.getWithAccounts(id);
    }

    @GetMapping("/{id}/full")
    public CustomerView fullView(@PathVariable String id) {
        return customerService.getFullView(id);
    }

    @GetMapping
    public List<CustomerView> all() {
        return customerService.getAllWithBatchFetch();
    }
}
