import org.mockito.junit.jupiter.MockitoExtension;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class CustomerServiceTest {

    @Mock CustomerRepository customerRepo;
    @InjectMocks CustomerService service;

    @Test
    void shouldLoadCustomerWithAccounts() {
        Customer customer = mock(Customer.class);
        when(customer.getCustomerId()).thenReturn("CUST-001");
        when(customer.getName()).thenReturn("Rajesh");
        when(customer.getEmail()).thenReturn("rajesh@bank.com");
        when(customer.getAccounts()).thenReturn(List.of());
        when(customer.getNominees()).thenReturn(Set.of());
        when(customerRepo.findByIdWithAccounts("CUST-001")).thenReturn(Optional.of(customer));

        CustomerView view = service.getWithAccounts("CUST-001");

        assertThat(view.customerId()).isEqualTo("CUST-001");
        verify(customerRepo).findByIdWithAccounts("CUST-001");  // JOIN FETCH query
    }
}
